#include <iostream>
#include "SparseMatrix.h"

// ---------------------------------------------------------------
// Construtor
// ---------------------------------------------------------------
SparseMatrix::SparseMatrix(int m, int n)
{
    if (m <= 0 || n <= 0)
    {
        std::cout << "Dimensões inválidas para a matriz: "
                  << m << " x " << n << std::endl;
        linhas = 0;
        colunas = 0;
        return;
    }

    linhas = m;
    colunas = n;
    vetorLinhas = new Node*[linhas]; // alocação do vetor de linhas
    for (int i = 0; i < linhas; i++)
        vetorLinhas[i] = nullptr; // inicializa todos os ponteiros

}

// ---------------------------------------------------------------
// Destrutor
// ---------------------------------------------------------------
SparseMatrix::~SparseMatrix()
{
    for (int i = 0; i < linhas; i++)
    {
        Node *atual = vetorLinhas[i];
        while (atual != nullptr)
        {
            Node *proximo = atual->proximo;
            delete atual;
            atual = proximo;
        }
        vetorLinhas[i] = nullptr;
    }
    delete[] vetorLinhas;
}

// ---------------------------------------------------------------
// Insere um valor na posição (i, j)
// ---------------------------------------------------------------
void SparseMatrix::inserir(int i, int j, double valor)
{
    if (i < 0 || i >= linhas || j < 0 || j >= colunas)
    {
        std::cout << "Célula inválida na matriz: (" << i << ", " << j << ")" << std::endl;
        return;
    }

    Node *novoNo = new Node(i, j, valor);
    novoNo->proximo = vetorLinhas[i];
    vetorLinhas[i] = novoNo;
}

// ---------------------------------------------------------------
// Retorna o valor na posição (i, j) (0.0 se não houver valor)
// ---------------------------------------------------------------
double SparseMatrix::get(int i, int j)
{
    if (i < 0 || i >= linhas || j < 0 || j >= colunas)
    {
        std::cout << "Célula inválida na matriz: (" << i << ", " << j << ")" << std::endl;
        return 0.0;
    }

    Node *atual = vetorLinhas[i];
    while (atual != nullptr)
    {
        if (atual->coluna == j)
            return atual->valor;
        atual = atual->proximo;
    }

    return 0.0;
}

// ---------------------------------------------------------------
// Imprime a matriz no formato denso
// ---------------------------------------------------------------
void SparseMatrix::imprimir()
{
    for (int i = 0; i < linhas; i++)
    {
        for (int j = 0; j < colunas; j++)
        {
            std::cout << get(i, j) << " ";
        }
        std::cout << std::endl;
    }
}

// ---------------------------------------------------------------
// Soma: C = A + B  (nome alterado de "soma" para "sum")
// ---------------------------------------------------------------
SparseMatrix* sum(SparseMatrix* A, SparseMatrix* B)
{
    if (A->getLinhas() != B->getLinhas() ||
        A->getColunas() != B->getColunas())
    {
        std::cout << "As matrizes devem ter as mesmas dimensões para realizar a soma." << std::endl;
        return nullptr;
    }

    SparseMatrix* C = new SparseMatrix(A->getLinhas(), A->getColunas());
    for (int i = 0; i < A->getLinhas(); i++)
    {
        for (int j = 0; j < A->getColunas(); j++)
        {
            double valorA = A->get(i, j);
            double valorB = B->get(i, j);
            C->inserir(i, j, valorA + valorB);
        }
    }

    return C;
}

// ---------------------------------------------------------------
// Multiplicação: C = A * B  (nome alterado de "multiplicacao" para "multiply")
// ---------------------------------------------------------------
SparseMatrix* multiply(SparseMatrix* A, SparseMatrix* B)
{
    if (A->getColunas() != B->getLinhas())
    {
        std::cout << "O número de colunas da matriz A deve ser igual ao número de linhas da matriz B para realizar a multiplicação." << std::endl;
        return nullptr;
    }

    SparseMatrix* C = new SparseMatrix(A->getLinhas(), B->getColunas());
    for (int i = 0; i < A->getLinhas(); i++)
    {
        for (int j = 0; j < B->getColunas(); j++)
        {
            double total = 0.0;
            for (int k = 0; k < A->getColunas(); k++)
            {
                total += A->get(i, k) * B->get(k, j);
            }
            C->inserir(i, j, total);
        }
    }

    return C;
}
